import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"雷地豫","description":"周易折中 - 雷地豫","frontmatter":{"title":"雷地豫","description":"周易折中 - 雷地豫"},"headers":[],"relativePath":"classics/zhezhong/022.md","filePath":"classics/zhezhong/022.md"}'),h={name:"classics/zhezhong/022.md"};function n(p,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="雷地豫" tabindex="-1">雷地豫 <a class="header-anchor" href="#雷地豫" aria-label="Permalink to “雷地豫”">​</a></h1><h3 id="程傳" tabindex="-1">程傳 <a class="header-anchor" href="#程傳" aria-label="Permalink to “程傳”">​</a></h3><p>豫序卦：“有大而能謙，必豫，故受之以豫。”承二卦之義而為次也。有既大而能謙，則有豫樂也。豫者，安和悅樂之義。為卦震上坤下，順動之象，動而和順，是以豫也。九四為動之主，上下群陰所共應也，坤又承之以順，是以動而上下順應，故為和豫之義。以二象言之，雷出於地上，陽始濳閉於地中，及其動而出地，奮發其聲，通暢和豫，故為豫也。</p><p>豫：利建侯行師</p><h3 id="本義" tabindex="-1">本義 <a class="header-anchor" href="#本義" aria-label="Permalink to “本義”">​</a></h3><p>豫，和樂也。人心和樂以應其上，九四一陽上下應之，其志得行。又以坤遇震，為順以動，故其卦為豫，而其佔利以立君用師也。</p><h3 id="程傳-1" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-1" aria-label="Permalink to “程傳”">​</a></h3><p>豫，順而動也。豫之義所利，在於建侯行師。夫建侯樹屏，所以共安天下，諸侯和順，則萬民悅服。兵師之興，眾心和悅，則順從而有功。故悅豫之道，利於建侯行師也。又上動而下順，諸侯從王，師眾順令之象，君萬邦聚大眾，非和悅不能使之服從也。</p><h3 id="集說" tabindex="-1">集說 <a class="header-anchor" href="#集說" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>孔氏穎達曰 ：謂之豫者，取逸豫之義。以和順而動，動不違眾，眾皆悅豫，故謂之豫也。動而眾悅，故利建侯；以順而動，故可以行師也。</p></li><li><p>邱氏富國曰 ：屯有震無坤，則言建侯而不言行師；謙有坤無震，則言行師而不言建侯。此合震坤成卦，故兼之。</p></li></ul><p>象曰：雷出地奮，豫；先王以作樂崇德，殷薦之上帝，以配祖考</p><h3 id="本義-1" tabindex="-1">本義 <a class="header-anchor" href="#本義-1" aria-label="Permalink to “本義”">​</a></h3><p>雷出地奮，和之至也。先王作樂，既象其聲，又取其義，殷盛也。</p><h3 id="程傳-2" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-2" aria-label="Permalink to “程傳”">​</a></h3><p>雷者，陽氣奮發，陰陽相薄而成聲也。陽始潛閉地中，及其動則出地奮震也。始閉鬱及奮發則通暢和豫，故為豫也。坤順震發，和順積中而發於聲樂之象也。先王觀雷出地而奮，和暢發於聲之象，作聲樂以褒崇功德，其殷盛至於薦之上帝，推配之以祖考，殷盛也。禮有殷奠，謂盛也。薦上帝配祖考，盛之至也。</p><h3 id="集說-1" tabindex="-1">集說 <a class="header-anchor" href="#集說-1" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>荀氏爽曰 ：樂者，聖人因人之豫而節之，所以養其正而閒其邪。其和可以感鬼神，而況於人乎？</p></li><li><p>鄭氏康成曰 ：奮動也。雷動於地上，萬物乃豫也。人至樂，則手欲鼓之，足欲舞之。王者功成作樂，以文得之者作龠舞，以武得之者作萬舞，各充其德而為制。祀天帝以配祖考者，使與天同饗其功也。故《孝經》雲：“郊祀后稷以配天，宗祀文王於明堂以配上帝”也。</p></li><li><p>胡氏炳文曰 ：本義雲“象其聲者”，樂之聲法雷之聲；“又取其義者”，豫以和為義。雷所以發揚化功而鼓天地之和，樂所以發揚功德而召神人之和也。</p></li></ul><p>彖曰：豫，剛應而志行，順以動，豫</p><h3 id="本義-2" tabindex="-1">本義 <a class="header-anchor" href="#本義-2" aria-label="Permalink to “本義”">​</a></h3><p>以卦體卦德釋卦名義。</p><h3 id="程傳-3" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-3" aria-label="Permalink to “程傳”">​</a></h3><p>剛應謂四為群陰所應，剛得眾應也。志行謂陽志上行動，而上下順從其志，得行也。順以動豫，震動而坤順，為動而順，順理而動，又為動而眾順，所以豫也。</p><h3 id="集說-2" tabindex="-1">集說 <a class="header-anchor" href="#集說-2" aria-label="Permalink to “集說”">​</a></h3><ul><li>胡氏炳文曰：建萬國，聚大眾，非順理而動，使人心皆和樂而從，不可也。故二者皆系之豫。案彖傳中凡稱卦德，皆先內而後外，而其文義又各不同。其曰“而”者，兩字並重，如訟之“險而健”，既險又健也；小畜之“健而巽”，既健又巽也；大有“剛健而文明”，既剛健而又文明也。其曰“以”者，則重在上一字，如同人“文明以健”，重在“文明”字。此卦“順以動”，重在“順”字。其或以下一字為重者，則又變其文法，如復卦“動而以順行”之類。</li></ul><p>豫，順以動，故天地如之，而況建侯行師乎</p><h3 id="本義-3" tabindex="-1">本義 <a class="header-anchor" href="#本義-3" aria-label="Permalink to “本義”">​</a></h3><p>以卦德釋卦辭。</p><h3 id="程傳-4" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-4" aria-label="Permalink to “程傳”">​</a></h3><p>以豫順而動，則天地如之而弗違，況建侯行師，豈有不順乎？天地之道，萬物之理，惟至順而已。大人所以先天后天而不違者，亦順乎理而已。</p><h3 id="集說-3" tabindex="-1">集說 <a class="header-anchor" href="#集說-3" aria-label="Permalink to “集說”">​</a></h3><ul><li>呉氏曰愼曰：順以動，所謂行其所無事也。天地如之，猶雲天且弗違。得其民者得其心也，故豫利建侯。多助之至，天下順之，故豫利行師。</li></ul><p>天地以順動，故日月不過，而四時不忒；聖人以順動，則刑罰清而民服。豫之時義大矣哉</p><h3 id="本義-4" tabindex="-1">本義 <a class="header-anchor" href="#本義-4" aria-label="Permalink to “本義”">​</a></h3><p>極言之而贊其大也。</p><h3 id="程傳-5" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-5" aria-label="Permalink to “程傳”">​</a></h3><p>復詳言順動之道。天地之運，以其順動，所以日月之度不過差，四時之行不愆忒。聖人以順動，故經正而民興於善，刑罰清簡而萬民服也。既言豫順之道矣，然其旨味淵永，言盡而意有餘也，故復贊之雲：“豫之時義大矣哉”，欲人研味其理，優柔涵泳而識之也。時義謂豫之時義，諸卦之時與義用大者，皆贊其大矣哉。豫以下十一卦是也。豫、遁、姤、旅言時義，坎、睽、蹇言時用，頤、大過、解、革言時，各以其大者也。</p><h3 id="集說-4" tabindex="-1">集說 <a class="header-anchor" href="#集說-4" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>項氏安世曰：豫、隨、遁、姤、旅皆若淺事而有深意，故曰時義大矣哉，欲人之思之也。坎、睽、蹇皆非美事，而聖人有時而用之，故曰時用大矣哉，欲人之別之也。頤、大過、解、革皆大事大變也，故曰時大矣哉，欲人之謹之也。</p></li><li><p>呉氏澄曰：專言時者，重在時字；時義，重在義字；時用，重在用字。</p></li><li><p>蔡氏清曰：時之一字，貫六十四卦皆有，不止豫等諸卦耳。有時則有義，有義則有用。單言時，則義與用在其中矣。言義未嘗無用，言用未嘗無義，各就所切而言。</p></li></ul><p>初六：鳴豫兇。</p><h3 id="本義-5" tabindex="-1">本義 <a class="header-anchor" href="#本義-5" aria-label="Permalink to “本義”">​</a></h3><p>陰柔小人上有強援，得時主事，故不勝其豫而以自鳴兇之道也。故其佔如此卦之得名本為和樂，然卦辭為眾樂之義。爻辭除九四與卦同外，皆為自樂，所以有吉凶之異。</p><h3 id="程傳-6" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-6" aria-label="Permalink to “程傳”">​</a></h3><p>初六以陰柔居下，四豫之主也，而應之是不中正之小人處，豫而為上所寵，其志意滿極不勝其豫，至發於聲音輕淺，如是必至於兇也。鳴發於聲也。</p><h3 id="集說-5" tabindex="-1">集說 <a class="header-anchor" href="#集說-5" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>石氏介曰：四為豫之主，初與之相應，小人得志必極其情慾以至於兇，形於聲鳴，豫之甚也。</p></li><li><p>蘇氏軾曰：所以為豫者四也，而初和之，故曰鳴已無以自樂，而恃其配以為樂，不得不兇。</p></li><li><p>王氏應麟曰：鳴謙則吉，鳴豫則兇，鳴者心聲之發也。</p></li><li><p>龔氏煥曰：豫之初六即謙上六之反對，故謙上六曰鳴謙，豫初六曰鳴豫，謙之上六應九三，故鳴其謙豫之初六，應九四，故不勝其豫以自鳴，謙而鳴則吉，豫而鳴則兇。</p></li></ul><p>象曰：初六鳴豫，志窮兇也</p><h3 id="本義-6" tabindex="-1">本義 <a class="header-anchor" href="#本義-6" aria-label="Permalink to “本義”">​</a></h3><p>窮謂滿極。</p><h3 id="程傳-7" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-7" aria-label="Permalink to “程傳”">​</a></h3><p>初六謂其以陰柔處下而志意窮極，不勝其豫，至於鳴也，必驕肆而致兇矣。</p><h3 id="集說-6" tabindex="-1">集說 <a class="header-anchor" href="#集說-6" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>楊氏簡曰 ：位之在下，未為窮也。豫而鳴，其志窮矣。</p></li><li><p>趙氏汝梅曰 ：位方在初，時勢未窮而競躁如此，是志已先窮，自取其兇者也。</p></li></ul><p>六二：介於石，不終日，貞吉。</p><h3 id="本義-7" tabindex="-1">本義 <a class="header-anchor" href="#本義-7" aria-label="Permalink to “本義”">​</a></h3><p>豫雖主樂，然易以溺人，溺則反而憂矣。卦獨此爻中而得正，是上下皆溺於豫，而獨能以中正自守，其介如石也。其德安靜而堅確，故其思慮明審，不俟終日而見凡事之幾微也。大學曰，安而後能慮，慮而後能得意，正如此佔者如是則正而吉矣。</p><h3 id="程傳-8" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-8" aria-label="Permalink to “程傳”">​</a></h3><p>逸豫之道放則失正，故豫之諸爻多不得正才與時合也。惟六二一爻處中正，又無應為自守之象，當豫之時獨能以中正自守，可謂特立之操，是其節介如石之堅也。介於石，其介如石也。人之於豫樂心悅之故，遲遲遂至於耽戀，不能已也。二以中正自守，其介如石，其去之速，不俟終日，故貞正而吉也。處豫不可安且久也，久則溺矣。如二可謂見幾而作者也。夫子因二之見幾而極言知幾之道，曰，知幾其神乎。君子上交不諂，下交不瀆，其知幾乎。幾者動之微，吉之先見者也。君子見幾而作，不俟終日。易曰，介於石，不終日，貞吉。介如石，焉寧用終日斷可識矣。君子知微，知彰，知柔，知剛，萬夫之望。夫見事之幾微者，其神妙矣乎。君子上交不至於諂，下交不至於瀆者，蓋知幾也。不知幾則至於過而不已，交於上以恭巽，故過則為諂，交於下以和易，故過則為瀆。君子見於幾微，故不至於過也。所謂幾者，始動之微也，吉凶之端可先見而未著者也。獨言吉者，見之於先，豈復至有兇也。君子明哲，見事之幾微，故能其介如石，其守既堅，則不惑而明，見幾而動，豈俟終日也，斷別也，其判別可見矣。微與彰，柔與剛，相對者也。君子見微則知彰矣，見柔則知剛矣。知幾如是，眾所仰也，故贊之曰，萬夫之望。</p><h3 id="集說-7" tabindex="-1">集說 <a class="header-anchor" href="#集說-7" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>王氏宗傳曰：凡人之情於逸豫之事，心焉悅之，必至於耽戀而不捨，何者有所溺故也。惟知幾之君子，其視樂豫之事，如將浼已，斷而識之速而去之，又豈俟終日也哉。此其所以當豫之時而獲吉也。</p></li><li><p>丘氏富國曰：豫諸爻以無所繫應者為吉，豫初應四而三五比四皆有系者也，是以為兇，為悔，為疾。獨六二陰靜而中正，與四無系，特立於眾陰之中，而無遲遲耽戀之意，方其靜也則確然自守，而介於石。及其動也則見幾而作，不俟終日，蓋其所居得正，故動靜之閒不失其正，吉可知矣。</p></li></ul><p>象曰：不終日貞吉，以中正也</p><h3 id="程傳-9" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-9" aria-label="Permalink to “程傳”">​</a></h3><p>能不終日而貞且吉者，以有中正之德也。中正故其守堅而能辨之早，去之速。爻言六二處豫之道，為教之意深矣。</p><h3 id="集說-8" tabindex="-1">集說 <a class="header-anchor" href="#集說-8" aria-label="Permalink to “集說”">​</a></h3><ul><li>黃氏淳耀曰 ：中正即介石意，是推明所以不終日之故。</li></ul><p>六三：盱豫，悔遲，有悔。</p><h3 id="本義-8" tabindex="-1">本義 <a class="header-anchor" href="#本義-8" aria-label="Permalink to “本義”">​</a></h3><p>盱上視也，陰不中正而近於四，四為卦主，故六三上視於四而下溺於豫，宜有悔者也。故其象如此，而其佔為事當速悔，若悔之遲，則必有悔也。</p><h3 id="程傳-10" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-10" aria-label="Permalink to “程傳”">​</a></h3><p>六三陰而居陽，不中不正之人也，以不中正而處豫，動皆有悔。盱上視也，上瞻望於四，則以不中正不為四所取，故有悔也。四豫之主與之切近，苟遲遲而不前，則見棄絕，亦有悔也。蓋處身不正，進退皆有悔吝，當如之何，在正身而已。君子處已有道以禮制心，雖處豫時不失中正，故無悔也。</p><h3 id="集說-9" tabindex="-1">集說 <a class="header-anchor" href="#集說-9" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>郭氏忠孝曰：處豫之道，戒在不能自立而優遊無斷，睢盱上視而悅之，非介於石者也，遲疑而有待，非不終日者也。</p></li><li><p>胡氏炳文曰：二中而得正，三陰不中正，故盱豫與介石相反，遲與不終日相反，中正與不中正故也。六三雖柔其位，陽猶有能悔之意，然悔之速可也，悔之遲則又必有悔矣。</p></li></ul><p>象曰：盱豫有悔，位不當也</p><h3 id="程傳-11" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-11" aria-label="Permalink to “程傳”">​</a></h3><p>自處不當，失中正也，是以進退有悔。</p><h3 id="集說-10" tabindex="-1">集說 <a class="header-anchor" href="#集說-10" aria-label="Permalink to “集說”">​</a></h3><ul><li>王氏申子曰 ：此爻與六二相反，盱則不能介於石，遲則不能不終日，中正與不中正故也。</li></ul><p>九四：由豫大有得，勿疑朋盍簪。</p><h3 id="本義-9" tabindex="-1">本義 <a class="header-anchor" href="#本義-9" aria-label="Permalink to “本義”">​</a></h3><p>九四卦之所由以為豫者也，故其象如此，而其佔為大有得。然又當至誠不疑，則朋類合而從之矣。故又因而戒之，簪聚也，又速也。</p><h3 id="程傳-12" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-12" aria-label="Permalink to “程傳”">​</a></h3><p>豫之所以為豫者由九四也，為動之主，動而眾陰悅順，為豫之義。四大臣之位，六五之君順從之以陽剛而任上之事，豫之所由也。故云由豫大有得，言得大行其志以致天下之豫也。勿疑朋盍簪，四居大臣之位，承柔弱之君而當天下之任，危疑之地也。獨當上之倚任，而下無同德之助，所以疑也。唯當盡其至誠，勿有疑慮，則朋類自當盍聚。欲上下之信，唯至誠而已。苟盡其至誠，則何患乎其無助也。簪聚也，簪之名簪取聚發也。或曰，卦唯一陽，安得同德之助。曰，居上位而至誠求助，理必得之。姤之九五曰，有隕自天，是也。四以陽剛迫近君位，而專主乎豫，聖人宜為之戒，而不然者，豫和順之道也。由和順之道，不失為臣之正也。如此而專主於豫，乃是任天下之事，而致時於豫者也。故唯戒以至誠，勿疑。</p><h3 id="集說-11" tabindex="-1">集說 <a class="header-anchor" href="#集說-11" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>侯氏行果曰：為豫之主，眾陰所宗，莫不由之以得其逸體，剛心直志，不懷疑，故得群物依歸，朋從大合，若以簪篸之固括也。</p></li><li><p>耿氏南仲曰：九四為震之主，以象言之，萬物莫不由雷以豫，以爻言之，五陰莫不由陽以豫，是以大有得也。大有得而勿疑，乃能協眾力以安其上，猶簪之總眾發以安其冠，若自疑則眾斯睽矣，未聞疑事而有功者也。</p></li><li><p>梁氏寅曰：由豫者，言人心之和豫由四而致也，處近君之地以剛而能柔，眾陰之所順附，此所謂大有得也。然人既樂從，則當開誠心布公道，待以曠大之度，不為物我之私，然後有以致人心之皆服，故曰勿疑朋盍簪。</p></li><li><p>蔡氏清曰：九四由豫大有得矣，又必戒以勿疑朋盍簪，者誠以由豫任大責重，難以獨力，必得同德者以自輔。自古以聖哲之資而居元臣之任者如舜，則舉八元八凱，伊尹周公，皆有俊乂吉人之助。諸葛孔明亦必開誠心以來諸賢之益，聖人命辭之意深矣哉。</p></li><li><p>何氏楷曰：簪聚也，簪之名簪取聚髪也。或謂古冠服無簪，按鹽鐵論神禹治水遺簪不顧，非簪而何，即弁服之笄是也。</p></li></ul><p>象曰：由豫大有得，志大行也</p><h3 id="程傳-13" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-13" aria-label="Permalink to “程傳”">​</a></h3><p>由己而致天下於樂豫，故為大有得，謂其志得大行也。</p><h3 id="集說-12" tabindex="-1">集說 <a class="header-anchor" href="#集說-12" aria-label="Permalink to “集說”">​</a></h3><ul><li>喬氏中和曰 ：剛應而志行，蓋由四以陽剛為群陰所應，故其志得以大行也。</li></ul><p>六五：貞疾恆不死。</p><h3 id="本義-10" tabindex="-1">本義 <a class="header-anchor" href="#本義-10" aria-label="Permalink to “本義”">​</a></h3><p>當豫之時以柔居尊，沈溺於豫，又乘九四之剛，眾不附而處勢危，故為貞疾之象。然以其得中，故又為常不死之象，即象而觀佔在其中矣。</p><h3 id="程傳-14" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-14" aria-label="Permalink to “程傳”">​</a></h3><p>六五以陰柔居君位，當豫之時沈溺於豫，不能自立者也。權之所主，眾之所歸，皆在於四，四之陽剛得眾，非耽惑柔弱之君所能制也。乃柔弱不能自立之君，受制於專權之臣也。居得君位貞也，受制於下有疾苦也。六五尊位權雖失，而位未亡也，故云貞疾恆不死，言貞而有疾，常疾而不死，如漢魏末世之君也。人君致危亡之道非一，而以豫為多，在四不言失正，而於五乃見其強逼者。四本無失故，在四言大臣任天下之事之義，在五則言柔弱居尊不能自立，威權去巳之義，各據爻以取義，故不同也。若五不失君道而四主於豫，乃是任得其人，安享其功如太甲成王也。䝉亦以陰居尊位，二以陽為䝉之主，然彼吉而此疾者時不同也。童蒙而資之於人宜也，耽豫而失之於人危亡之道也。故蒙相應則倚任者也，豫相逼則失權者也，又上下之心專歸於四也。</p><h3 id="集說-13" tabindex="-1">集說 <a class="header-anchor" href="#集說-13" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>王氏宗傳曰：當逸豫之時恣驕侈之慾，宜其死於安樂有餘也。然乘九四之剛，恃以拂弼於巳，故得恆不死也。孟子曰，入則無法家拂士，出則無敵國外患者國恆亡，然後知生於憂患而死於安樂也。則六五之得九四得法家拂士也，故雖當豫之時不得以縱其所樂，唯不得以縱其所樂則恆不死宜也。夫當豫之時而不為豫者以正自守也，六二是也。當豫之時而不得豫者，見正於人也，六五是也。此豫之六爻惟六二六五所以不言豫焉。</p></li><li><p>何氏楷曰：六五以柔居尊，當豫之時易於沈溺，必戰兢畏惕，常如疾病在身，乃得恆而不死，所謂生於憂患者也。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>王民何氏說深得爻義。</p><p>象曰：六五貞疾，乘剛也；恆不死，中未亡也</p><h3 id="程傳-15" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-15" aria-label="Permalink to “程傳”">​</a></h3><p>貞而疾，由乘剛為剛所逼也；恆不死，中之尊位未亡也。</p><h3 id="集說-14" tabindex="-1">集說 <a class="header-anchor" href="#集說-14" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>楊氏時曰 ：居豫之時，無剛健之才，逸於豫者也。孟子曰：“入則無法家拂士，出則無敵國外患者，國常亡。”六五之乘剛，有法家拂士、敵國外患之謂也。左右救正之故，以正為疾，雖未能執其中而中未亡，則不死於安樂矣。故常不死。</p></li><li><p>鄭氏汝諧曰 ：二與五皆不言豫，二靜晦不為豫也，五乘剛不敢豫也。若人得一固疾，雖不快於己，亦足以久其生者，有戒心也。是以終未亡而常存。</p></li><li><p>胡氏炳文曰 ：豫最易以溺人。六二柔中且正，能不終日而去之；六五陰柔不正，未免溺於豫矣。猶得不死者，中未亡也。人莫不生於憂患而死於逸樂，以六五之中僅得不死，然則初之鳴、三之盱、上之冥，其不中者皆非生道矣。</p></li></ul><p>上六：冥豫成，有渝無咎。</p><h3 id="本義-11" tabindex="-1">本義 <a class="header-anchor" href="#本義-11" aria-label="Permalink to “本義”">​</a></h3><p>以陰柔居豫極，為昏冥於豫之象。以其動體，故又為其事雖成而能有渝之象。戒佔者如是則能補過而無咎，所以廣遷善之門也。</p><h3 id="程傳-16" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-16" aria-label="Permalink to “程傳”">​</a></h3><p>上六陰柔非有中正之德，以陰居上不正也。而當豫極之時，以君子居斯時，亦當戒懼。況陰柔乎，乃耽肆於豫，昏迷不知反者也。在豫之終，故為昏冥已成也。若能有渝變，則可以無咎矣。在豫之終有變之義，人之失若能自變皆可以無咎。故冥豫雖已成，能變則善也。聖人發此義，所以勸善也，故更不言冥之兇，專言渝之無咎。</p><h3 id="集說-15" tabindex="-1">集說 <a class="header-anchor" href="#集說-15" aria-label="Permalink to “集說”">​</a></h3><ul><li>王氏應麟曰：冥於豫而勉其有渝，開遷善之門也。冥於升而勉其不息，回進善之機也。</li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>貞疾與成有渝兩爻之義亦相為首尾，如人之耽於逸樂而不能節其飲食起居者，是致死之道也。苟使縱其欲而無病，則將一病不支而亡也無日矣。惟其常有疾也，故常能憂懼儆戒而得不死也。然所貴乎憂懼儆戒者，以其能改變爾向也。耽於逸樂昏冥而不悟，殆將習與性成矣。今乃一變所為，而節飲食愼起居，則可以復得其性命之理。豈獨不死而已乎，故於五不言無咎，而於上言之所以終卦義而垂至戒也。</p><p>象曰：冥豫在上，何可長也</p><h3 id="程傳-17" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-17" aria-label="Permalink to “程傳”">​</a></h3><p>昏冥於豫，至於終極，災咎行及矣，其可長然乎？當速渝也。</p><h3 id="集說-16" tabindex="-1">集說 <a class="header-anchor" href="#集說-16" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>胡氏瑗曰 ：何可長者，言其悅豫過甚，至於情蕩性冥而不知所止，是何可長如此乎？言能渝變則可以無咎也。</p></li><li><p>王氏申子曰 ：豫至於上極矣，極則不可以久，速渝可也。</p></li></ul>',116)])])}const m=e(h,[["render",n]]);export{b as __pageData,m as default};
